const CORS = {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Methods":"GET,POST,PUT,DELETE,OPTIONS","Access-Control-Allow-Headers":"Content-Type"};

function getMimeType(p) {
  const ext = p.slice(p.lastIndexOf("."));
  return {".html":"text/html; charset=utf-8",".js":"application/javascript; charset=utf-8",".css":"text/css; charset=utf-8",".svg":"image/svg+xml",".json":"application/json",".png":"image/png",".jpg":"image/jpeg",".ico":"image/x-icon",".woff2":"font/woff2",".woff":"font/woff"}[ext] || "application/octet-stream";
}

async function handleApi(context) {
  const {request} = context;
  const url = new URL(request.url);
  const path = url.pathname;
  
  // 安全获取 KV 实例
  let kv = null;
  try {
    kv = TEXTDB;
  } catch (e) {
    return new Response(JSON.stringify({
      status: 0, 
      error: "KV 命名空间 'TEXTDB' 未绑定。请在 EdgeOne Pages 逻辑设置中绑定 KV 实例，变量名设为 TEXTDB。",
      tip: "进入 EdgeOne 控制台 -> Pages -> 你的项目 -> 边缘函数设置 -> KV 绑定"
    }), {status: 500, headers: {...CORS, "Content-Type": "application/json"}});
  }

  if (request.method === "OPTIONS") return new Response(null, {status:204, headers:CORS});

  // POST /update/
  if (path === "/update/" || path === "/update") {
    if (request.method !== "POST") {
      return new Response(JSON.stringify({status:0,error:"请使用 POST 方法"}), {status:405, headers:{...CORS,"Content-Type":"application/json"}});
    }
    const ct = (request.headers.get("content-type")||"").toLowerCase();
    let params = {};
    try {
      if (ct.includes("json")) params = await request.json();
      else if (ct.includes("form")) { const fd = await request.formData(); params = Object.fromEntries(fd.entries()); }
    } catch(e) {}
    const key = (params.key||"").trim();
    const value = params.value;
    if (!/^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response(JSON.stringify({status:0,error:"key 格式错误"}), {status:400, headers:{...CORS,"Content-Type":"application/json"}});
    }
    if (value === "" || value === undefined || value === null) {
      await kv.delete(key);
      return new Response(JSON.stringify({status:1,data:{key,url:url.origin+"/"+key,action:"deleted"},req_id:Math.random().toString(36).slice(2,18)}), {headers:{...CORS,"Content-Type":"application/json"}});
    }
    if (typeof value !== "string" || value.length > 200000) {
      return new Response(JSON.stringify({status:0,error:"value 不能为空且不能超过 20 万字符"}), {status:400, headers:{...CORS,"Content-Type":"application/json"}});
    }
    await kv.put(key, value);
    return new Response(JSON.stringify({status:1,data:{key,url:url.origin+"/"+key},req_id:Math.random().toString(36).slice(2,18)}), {headers:{...CORS,"Content-Type":"application/json"}});
  }

  // GET /{key}
  if (request.method === "GET") {
    const key = path.slice(1);
    if (!/^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response("", {headers:{...CORS,"Content-Type":"text/plain"}});
    }
    const val = await kv.get(key);
    return new Response(val || "", {headers:{...CORS,"Content-Type":"text/plain; charset=utf-8"}});
  }

  // POST /{key}
  if (request.method === "POST") {
    const key = path.slice(1);
    if (!/^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response(JSON.stringify({status:0,error:"key 格式错误"}), {status:400, headers:{...CORS,"Content-Type":"application/json"}});
    }
    const ct = (request.headers.get("content-type")||"").toLowerCase();
    let value = ct.includes("json") ? await request.json().then(b => typeof b==="string"?b:JSON.stringify(b)) : await request.text();
    if (!value) { await kv.delete(key); return new Response(JSON.stringify({status:1,data:{key,action:"deleted"},req_id:Math.random().toString(36).slice(2,18)}), {headers:{...CORS,"Content-Type":"application/json"}}); }
    if (value.length > 200000) return new Response(JSON.stringify({status:0,error:"value 不能超过 20 万字符"}), {status:400, headers:{...CORS,"Content-Type":"application/json"}});
    await kv.put(key, value);
    return new Response(JSON.stringify({status:1,data:{key,url:url.origin+"/"+key},req_id:Math.random().toString(36).slice(2,18)}), {headers:{...CORS,"Content-Type":"application/json"}});
  }

  // DELETE /{key}
  if (request.method === "DELETE") {
    const key = path.slice(1);
    if (!/^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response(JSON.stringify({status:0,error:"key 格式错误"}), {status:400, headers:{...CORS,"Content-Type":"application/json"}});
    }
    await kv.delete(key);
    return new Response(JSON.stringify({status:1,data:{key,action:"deleted"},req_id:Math.random().toString(36).slice(2,18)}), {headers:{...CORS,"Content-Type":"application/json"}});
  }

  return new Response(JSON.stringify({status:0,error:"不支持的请求方式"}), {status:405, headers:{...CORS,"Content-Type":"application/json"}});
}

export default function onRequest(context) {
  try {
    const url = new URL(context.request.url);
    const path = url.pathname;

    // Static files
    if (path === "/" || path === "/index.html") {
      const html = STATIC_FILES["/index.html"];
      if (html) return new Response(html, {headers:{"Content-Type":"text/html; charset=utf-8",...CORS}});
    }
    if (STATIC_FILES[path]) {
      return new Response(STATIC_FILES[path], {headers:{"Content-Type":getMimeType(path),...CORS}});
    }

    // API routes
    return handleApi(context);
  } catch(e) {
    return new Response(JSON.stringify({status:0, error:e.message, stack:e.stack, name:e.name}), {status:500, headers:{...CORS,"Content-Type":"application/json"}});
  }
}
